import { describe, it } from "vitest";

describe("MHPCO claim office", () => {
  // --- Quote: simplest case and single items ---
  it.todo("empty item list -> premium 5 G (processing fee only)");
  it.todo("single plain sword -> base premium 100 G");
  it.todo("single plain amulet -> base premium 60 G");
  it.todo("single plain staff -> base premium 80 G");
  it.todo("single plain potion -> base premium 40 G");

  // --- Components and the block of 3 alike ---
  it.todo("2 runes -> 50 G base premium (no block)");
  it.todo("3 runes -> 60 G base premium (block applies)");
  it.todo("4 runes -> 100 G base premium (no block -- block requires exactly 3)");
  it.todo("7 runes -> 175 G base premium (no block for 7)");
  it.todo("2 runes + 1 moonstone -> 75 G base premium (alike means same type)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword adds 50 % of its base premium as risk surcharge");
  it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge (threshold inclusive)");
  it.todo("sword with enchantment 4 adds no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 adds both surcharges");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("second quote in a scenario receives the 15 % follow-up contract discount");
  it.todo("every quote carries the 10 % first insurance surcharge on the policy base premium");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet -> curse surcharge is 50 G (50 % of the cursed item only)");

  // --- Rounding ---
  it.todo("premium of 197.5 G rounds up to 198 G (MHPCO's favor)");
  it.todo("payout of 350.5 G rounds down to 350 G (MHPCO's favor)");

  // --- Quote errors ---
  it.todo("quote with an unknown item type throws an Error (CLI exits non-zero)");

  // --- Claim: standard reimbursement ---
  it.todo("steel sword enchantment 3, damage 500 G -> payout 400 G (deductible only)");
  it.todo("rune (no enchantment, no material), damage 200 G -> payout 100 G");

  // --- Claim: special clauses ---
  it.todo("steel sword enchantment 9, damage 1000 G -> payout 400 G (50 % then deductible)");
  it.todo("dragon sword enchantment 5, damage 800 G -> payout 700 G (full, then deductible)");
  it.todo("dragon sword enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins)");
  it.todo("dragon sword enchantment 8, damage 1000 G -> payout 400 G (threshold inclusive)");

  // --- Claim: deductible per damage event ---
  it.todo("sword 500 G + amulet 300 G in one incident -> payout 600 G (deductible per item)");

  // --- Claim: cap ---
  it.todo("policy of sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("policy of sword + 3 runes -> insurance sum 1750 G (block affects premium only)");
  it.todo("cursed sword -> cap 2000 G based on the unmodified insurance value");
  it.todo("two successive 1500 G claims on a sword -> payouts 1400 G then 600 G, cap remaining 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("policy with two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damages against two insured swords -> each has its own deductible");
  it.todo("more damages of a type than insured items throws an Error (CLI exits non-zero)");

  // --- Claim errors ---
  it.todo("claim for an item not part of the policy throws an Error (CLI exits non-zero)");
  it.todo("claim with a negative damage amount throws an Error (CLI exits non-zero)");

  // --- Integration examples ---
  it.todo("newcomer with a cursed sword -> premium 165 G");
  it.todo("long-standing customer's second contract, cursed sword ench. 7 -> premium 160 G");

  // --- CLI ---
  it.todo("CLI reads the schema example from stdin and writes the results JSON to stdout");
  it.todo("CLI exits non-zero and writes to stderr for an unknown item type");
});

