const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = { sword: 100 };

function itemBasePremium(item: Item): number {
  return BASE_PREMIUMS[item.type];
}

function quotePremium(items: Item[]): number {
  const policyBase = items.reduce((sum, item) => sum + itemBasePremium(item), 0);

  return Math.ceil(policyBase * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): StepResult[] {
  return scenario.steps.map((step) => ({
    premium: quotePremium((step as QuoteStep).items),
  }));
}

